def find_Min(arr, low, high):
    # Base case: if the array is empty or has only one element, return that element
    if low == high:
        return arr[low]

    # Find the middle index
    mid = (low + high) // 2

    # Check if the middle element is the minimum
    if arr[mid] < arr[mid + 1]:
        return arr[mid]

    # If the middle element is greater than the last element, the minimum is in the right half
    if arr[mid] > arr[high]:
        return find_Min(arr, mid + 1, high)

    # If the middle element is less than the first element, the minimum is in the left half
    return find_Min(arr, low, mid - 1)
