def first_Missing_Positive(arr, n):
    # Initialize the array with 1 to mark the presence of numbers
    arr = [1] * n

    # Iterate through the array
    for i in range(n):
        # If the element is not at its correct position (i + 1), swap it with its correct position
        if arr[i] != i + 1:
            arr[arr[i] - 1], arr[i] = arr[i], arr[arr[i] - 1]

    # Find the first index where the element is not equal to its correct position
    for i in range(n):
        if arr[i] != i + 1:
            return i + 1

    # If no missing positive number is found, return n + 1
    return n + 1
